  def check_concrete_output(mission_facts: Mining_Threat_Retreat_Supervisor.Mission_Facts => B,
                            arrival_fact: Mining_Threat_Retreat_Supervisor.Arrival_Fact => B,
                            mission_invalidity: Mining_Threat_Retreat_Supervisor.Mission_Invalidity_Facts => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val mission_factsValue: Mining_Threat_Retreat_Supervisor.Mission_Facts = get_mission_facts().get
    if(!mission_facts(mission_factsValue)) {
      testFailures = testFailures :+ st"'mission_facts' did not match expected: value of the outgoing data port is ${mission_factsValue}"
    }
    val arrival_factValue: Mining_Threat_Retreat_Supervisor.Arrival_Fact = get_arrival_fact().get
    if(!arrival_fact(arrival_factValue)) {
      testFailures = testFailures :+ st"'arrival_fact' did not match expected: value of the outgoing data port is ${arrival_factValue}"
    }
    val mission_invalidityValue: Mining_Threat_Retreat_Supervisor.Mission_Invalidity_Facts = get_mission_invalidity().get
    if(!mission_invalidity(mission_invalidityValue)) {
      testFailures = testFailures :+ st"'mission_invalidity' did not match expected: value of the outgoing data port is ${mission_invalidityValue}"
    }

    assert(testFailures.isEmpty, st"${(testFailures, "\n")}".render)
  }


